import json, sys

path = sys.argv[1]
out_path = sys.argv[2]

def trunc(s, n=400):
    if s is None:
        return ""
    s = str(s)
    if len(s) > n:
        return s[:n] + f"...[{len(s)}chars]"
    return s

with open(path) as f, open(out_path, "w") as out:
    for i, line in enumerate(f):
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except Exception as e:
            out.write(f"[{i}] PARSE_ERROR {e}\n")
            continue
        t = d.get("type")
        ts = d.get("timestamp") or (d.get("message") or {}).get("timestamp") or ""
        if t in ("user", "assistant"):
            msg = d.get("message", {})
            role = msg.get("role", t)
            content = msg.get("content")
            if isinstance(content, str):
                out.write(f"[{i}] {ts} {role} TEXT: {trunc(content, 600)}\n")
            elif isinstance(content, list):
                for block in content:
                    if not isinstance(block, dict):
                        continue
                    bt = block.get("type")
                    if bt == "text":
                        out.write(f"[{i}] {ts} {role} TEXT: {trunc(block.get('text'), 600)}\n")
                    elif bt == "tool_use":
                        name = block.get("name")
                        inp = trunc(json.dumps(block.get("input", {})), 250)
                        out.write(f"[{i}] {ts} {role} TOOL_USE {name}: {inp}\n")
                    elif bt == "tool_result":
                        c = block.get("content")
                        if isinstance(c, list):
                            c = " ".join(trunc(cc.get("text",""), 150) for cc in c if isinstance(cc, dict))
                        out.write(f"[{i}] {ts} {role} TOOL_RESULT: {trunc(c, 200)}\n")
                    else:
                        out.write(f"[{i}] {ts} {role} {bt}\n")
        elif t == "attachment":
            att = d.get("attachment", {})
            at = att.get("type")
            out.write(f"[{i}] {ts} ATTACH {at}: {trunc(att.get('content') or att.get('stdout'), 150)}\n")
        elif t == "ai-title":
            out.write(f"[{i}] AI_TITLE: {d.get('aiTitle')}\n")
        else:
            out.write(f"[{i}] {t}\n")
print("done", out_path)

