import json, sys

def trunc(s, n=500):
    if not isinstance(s, str):
        s = json.dumps(s)
    if len(s) > n:
        return s[:n] + f"...[TRUNCATED, total {len(s)} chars]"
    return s

def content_to_text(content):
    if isinstance(content, str):
        return trunc(content)
    if isinstance(content, list):
        parts = []
        for block in content:
            if not isinstance(block, dict):
                parts.append(trunc(str(block), 200))
                continue
            t = block.get("type")
            if t == "text":
                parts.append("[text] " + trunc(block.get("text",""), 600))
            elif t == "tool_use":
                parts.append(f"[tool_use:{block.get('name')}] " + trunc(block.get("input"), 400))
            elif t == "tool_result":
                c = block.get("content")
                if isinstance(c, list):
                    ctext = " ".join(x.get("text","") if isinstance(x,dict) else str(x) for x in c)
                else:
                    ctext = c
                is_err = block.get("is_error")
                parts.append(f"[tool_result{' ERROR' if is_err else ''}] " + trunc(ctext, 400))
            else:
                parts.append(f"[{t}] " + trunc(block, 200))
        return "\n".join(parts)
    return trunc(content)

def main(path):
    with open(path) as f:
        for i, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception as e:
                print(f"--- line {i}: PARSE ERROR {e}")
                continue
            typ = obj.get("type")
            ts = obj.get("timestamp", "")
            if typ in ("user", "assistant"):
                msg = obj.get("message", {})
                role = msg.get("role", typ)
                content = msg.get("content")
                text = content_to_text(content)
                print(f"--- line {i} [{ts}] {role} ---")
                print(text)
            elif typ in ("attachment", "queue-operation", "ai-title"):
                pass
            else:
                print(f"--- line {i} [{ts}] type={typ} ---")
                print(trunc(obj, 300))

if __name__ == "__main__":
    main(sys.argv[1])

